<script setup>
import {useDashboard} from '../../composables/useDashboard';
const {deliveryStart,deliveryEnd,deliveryOrderQuery,flowSupplierQuery,flowBuyerQuery,flowOrderRows}=useDashboard();
</script>
<template>
<section class="page-stack"><div class="query-panel flow-query"><label>订单编号<input v-model="deliveryOrderQuery" placeholder="请输入订单编号"></label><label>供应商<input v-model="flowSupplierQuery" placeholder="请输入供应商名称"></label><label>采购员<input v-model="flowBuyerQuery" placeholder="请输入采购员"></label><label>开始日期<input type="date" v-model="deliveryStart"></label><label>结束日期<input type="date" v-model="deliveryEnd"></label><button>查询</button></div><article class="data-box order-detail-table"><header>采购订单与送货进度</header><div><table><thead><tr><th v-for="h in ['订单号','订单日期','采购员','供应商名称','订单笔数','订单状态','供应商受理','累计发货','累计收货','未收数量','送货单号']">{{h}}</th><th class="order-progress-heading"><span>订单进度</span><div class="order-progress-labels"><span v-for="step in ['请购','下单','确认','送货','到货检验','入库']" :key="step">{{step}}</span></div></th></tr></thead><tbody><tr v-for="x in flowOrderRows" :key="x.orderId"><td>{{x.orderId}}</td><td>{{x.orderDate}}</td><td>{{x.buyer}}</td><td>{{x.supplier}}</td><td>{{x.lineCount}}笔</td><td><span :class="['flow-status',x.orderStatus]">{{x.orderStatus}}</span></td><td>{{x.acceptanceStatus}}</td><td>{{x.hasShipment?x.shipped:'-'}}</td><td>{{x.hasShipment?x.received:'-'}}</td><td>{{x.hasShipment?x.unreceived:'-'}}</td><td>{{x.deliveryNotes}}</td><td><div class="order-progress"><i v-for="(done,i) in x.progress" :key="i" :class="{done}"></i></div></td></tr><tr v-if="!flowOrderRows.length"><td colspan="12" class="empty-cell">暂无符合条件的订单</td></tr></tbody></table></div></article></section>
</template>
